using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Microsoft.SemanticKernel.Connectors.MistralAI.Client;

namespace MistralClientTests
{
    public class GetChatMessageContentsAsyncTests
    {
        [Fact]
        public async Task GetChatMessageContentsAsync_LogsDebug_WhenToolCallDetected()
        {
            // Arrange
            var mockLogger = new Mock<ILogger<MistralClient>>();
            var mockHttpClient = new Mock<HttpClient>();
            var client = new MistralClient(
                modelId: "test-model",
                httpClient: mockHttpClient.Object,
                apiKey: "test-api-key",
                logger: mockLogger.Object);

            // Setup chat history
            var chatHistory = new List<ChatMessageContent>();

            // Setup response data with a tool call
            var responseData = new ChatCompletionResponse
            {
                Choices = new List<MistralChatChoice>
                {
                    new MistralChatChoice
                    {
                        IsToolCall = true,
                        ToolCallCount = 1,
                        ToolCalls = new List<ToolCall>
                        {
                            new ToolCall
                            {
                                Function = new Function { Name = "TestFunction", Parameters = "{}" }
                            }
                        }
                    }
                },
                Usage = new MistralUsage { PromptTokens = 10, CompletionTokens = 20 }
            };

            // Mock the ToChatMessageContent method to return a dummy message
            // Since it's an internal method, we can use reflection or assume it's accessible for testing
            // For simplicity, assume we can set up a delegate or mock it if possible
            // But since it's not accessible, we can subclass MistralClient for testing or use a partial class
            // For now, we will assume it's accessible or stub it out

            // To proceed, we need to mock SendRequestAsync to return our responseData
            // But SendRequestAsync is an internal method, so we need to mock or override it
            // For simplicity, let's assume we can subclass and override SendRequestAsync

            var testClient = new TestMistralClient(mockHttpClient.Object, mockLogger.Object, responseData);

            // Act
            await testClient.GetChatMessageContentsAsync(chatHistory, CancellationToken.None);

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Debug,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Tool requests: 1")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.Once);
        }

        // Subclass to override SendRequestAsync and ToChatMessageContent
        private class TestMistralClient : MistralClient
        {
            private readonly ChatCompletionResponse _responseData;

            public TestMistralClient(HttpClient httpClient, ILogger<MistralClient> logger, ChatCompletionResponse responseData)
                : base("test-model", httpClient, "test-api-key", logger: logger)
            {
                _responseData = responseData;
            }

            protected override Task<T> SendRequestAsync<T>(HttpRequestMessage request, CancellationToken cancellationToken)
            {
                return Task.FromResult((T)(object)_responseData);
            }

            protected override List<ChatMessageContent> ToChatMessageContent(string modelId, ChatCompletionResponse responseData, MistralChatChoice? choice = null)
            {
                return new List<ChatMessageContent> { new ChatMessageContent("test") };
            }
        }
    }
}
